<template><div class="pagination"><span>第 {{start}}–{{end}} 条，共 {{total}} 条</span><div class="pages"><button class="page-button" :disabled="pageNo<=1" @click="change(pageNo-1)">‹</button><button v-for="page in pages" :key="page" class="page-button" :class="{active:page===pageNo}" @click="change(page)">{{page}}</button><button class="page-button" :disabled="pageNo>=pageCount" @click="change(pageNo+1)">›</button></div></div></template>
<script>export default{name:'AppPagination',props:{pageNo:{type:Number,default:1},pageSize:{type:Number,default:10},total:{type:Number,default:0}},emits:['change'],computed:{pageCount(){return Math.max(1,Math.ceil(this.total/this.pageSize));},pages(){const start=Math.max(1,Math.min(this.pageNo-2,this.pageCount-4));return Array.from({length:Math.min(5,this.pageCount)},(_,i)=>start+i);},start(){return this.total?(this.pageNo-1)*this.pageSize+1:0;},end(){return Math.min(this.pageNo*this.pageSize,this.total);}},methods:{change(page){if(page>=1&&page<=this.pageCount&&page!==this.pageNo)this.$emit('change',page);}}};</script>
